import React, { useState, useEffect } from 'react';
import { io } from 'socket.io-client';
import { useLocation } from 'react-router-dom';

const socket = io('http://localhost:5000');

const Messages = () => {

  const location = useLocation(); 
  const currentUser = location.state?.username || 'Guest'; 
  const [chatpartner, setchatpartner] = useState("");
    // State to track current message input
    const [message, setMessage] = useState("");

    // State to store the list of messages
    const [messageHistory, setMessageHistory] = useState([]);

    // Static user for this example
    // You can replace this with dynamic user data

    const getroomId = () => {
      return [currentUser,chatpartner].sort().join('-');
    }

    // Function to handle sending message
    const sendMessage = (e) => {
        e.preventDefault();
        console.log(messageHistory);
        console.log("the current user is :"+ currentUser)
        if (message.trim() === '') return; // Prevent sending empty messages

        const roomId = getroomId();

        const messageData = {
          roomId,
          user: currentUser,
          text: message,
        };

        // Emit the message to the server via socket
        socket.emit('chat message', messageData);

        // Add the sent message to the message history
        setMessageHistory((prevHistory) => [...prevHistory, messageData]);

        // Clear the input field
        setMessage("");
    };

    useEffect(() => {
      if (chatpartner) {
        const roomId = getroomId();

        // Join the room for the current conversation
        socket.emit('join-room', roomId);

        // Listen for messages from the server
        socket.on('receive message', (msg) => {
          setMessageHistory((prevHistory) => [...prevHistory, msg]); // Update message history
        });

        // Cleanup when the component unmounts or chat partner changes
        return () => {
          socket.emit('leave-room', roomId); // Leave the room when done
          socket.off('receive message'); // Remove the message listener
        };
      }
    }, [chatpartner, currentUser]);

  return (
    <div className='border-black border-[2px] h-[100vh] flex flex-row'>
      <div className='border-black border-2 h-full w-[25%]'>
       <div className='border-bottom h-[60px] border-black w-full flex items-center mt-1' >
       <div>
          profile
        </div>
        <div>search for friends</div>
       </div>
        <div className='border-black border-[2px] h-[50px] w-full flex items-center gap-2 mt-2'>
            <div className='flex border-[2px] border-black h-[35px] w-[35px] items-center justify-center rounded-[50%] ml-[5px]'>S</div>
            <label>Sagar</label>
        </div>
        <div className='border-black border-[2px] h-[50px] w-full flex items-center gap-2 mt-2'>
            <div className='flex border-[2px] border-black h-[35px] w-[35px] items-center justify-center rounded-[50%] ml-[5px]'>H</div>
            <label>Himanshu</label>
        </div>
        <div className='border-black border-[2px] h-[50px] w-full flex items-center gap-2 mt-2'>
            <div className='flex border-[2px] border-black h-[35px] w-[35px] items-center justify-center rounded-[50%] ml-[5px]'>A</div>
            <label>Angel Priya</label>
        </div>
        <div className='border-black border-[2px] h-[50px] w-full flex items-center gap-2 mt-2'>
            <div className='flex border-[2px] border-black h-[35px] w-[35px] items-center justify-center rounded-[50%] ml-[5px]'>J</div>
            <label>jim Halpert</label>
        </div>
        <div className='border-black border-[2px] h-[50px] w-full flex items-center gap-2 mt-2'>
            <div className='flex border-[2px] border-black h-[35px] w-[35px] items-center justify-center rounded-[50%] ml-[5px]'>V</div>
            <label>Venkatesh</label>
        </div>
      </div>
       <div className='border-black border-2 h-full w-full'>
       <div className='border-black border-2 h-[10vh] flex items-center pl-[10px] w-full'>
        <input type='text' placeholder='select chat partner' value={chatpartner} onChange={(e) => setchatpartner(e.target.value)}/>
        </div>
        {/* Displaying the message history */}
        <div className="flex flex-col h-[90vh]" >
          <div className='overflow-auto '>
            {messageHistory.map((msg, index) => (
            <div key={index}>
              <h2>{msg.text}</h2>
              {/* {msg.user == currentUser ? <h1>{msg.text} </h1> : <div>{msg.text}</div>} */}
            </div>
          ))
          }
          </div>
          {/* Input form to send messages */}
        <form onSubmit={sendMessage} className='flex w-full p-[5px] mt-auto justify-around'>
            <input 
                type='text' 
                value={message} 
                onChange={(e) => setMessage(e.target.value)} 
                placeholder="Type your message..."
                className='border-black border-[2px] outline-none w-[90%] rounded-[5px] h-[6vh] align-center pl-[8px]'
            />
            <button type="submit" className='h-[6vh] w-[9%] rounded-[10px] border-2 border-green-900 bg-green-500 text-white '>Send</button>
        </form>
        </div>
       </div>
    </div>
  )
}

export default Messages;
